            struct("IncludeSamples", true));
        collectionMetadataInfo = helperReadCollectionMetadata( ...
            fullfile(sessionData.DatasetRoot, "collection_metadata.json"), ...
            datasetId);
        g3SyncResults = helperAnalyzeG3SyncCore(sessionData, ...
            collectionMetadataInfo);
        pipelineResults = localRecordG3SyncResults(pipelineResults, ...
            g3SyncResults);
        g3SyncSummary = localBuildG3SyncReviewSummaryTable(g3SyncResults);
        g3SyncCpiDefinitions = localBuildG3SyncCpiDefinitionTable( ...
            g3SyncResults);
        g3SyncQuestionSummary = g3SyncResults.QuestionSummaries;
        g3SyncStrategySummary = localBuildG3SyncStrategySummaryTable( ...
            g3SyncResults);
        g3SyncInterpretationSummary = localBuildG3SyncInterpretationTable( ...
            g3SyncResults);
    catch analysisException
        g3SyncResults = struct();
        g3SyncSummary = localBuildBlockedSummaryTable( ...
            "G3 Sync Analysis Core", ...
            "Helper execution failed: " + ...
            string(analysisException.message));
    end
else
    g3SyncResults = struct();
    g3SyncSummary = localBuildBlockedSummaryTable( ...
        "G3 Sync Analysis Core", ...
        "Run G2 Stage 2 in this live-script session and establish " + ...
        "downstream development readiness before reviewing G3 sync.");
end
