        pipelineResults = localRecordG4PassiveBaselineMapResult( ...
            pipelineResults, "executed", g4PassiveBaselineMapAnalysis, "");
        pipelineResults.G4PassiveBaselineMapResult.BundleRoot = ...
            g4PassiveBaselineMapRunnerResults.BundleRoot;
        g4ReviewSummary = localBuildG4ReviewSummaryTable( ...
            g4PassiveBaselineMapAnalysis);
        g4QuestionSummary = g4PassiveBaselineMapAnalysis.QuestionSummaries;
        g4CpiComparison = localBuildG4CpiComparisonTable( ...
            g4PassiveBaselineMapAnalysis);
        g4MapLabelCounts = localBuildG4MapLabelCountTable( ...
            g4PassiveBaselineMapAnalysis.MapSummaryTable);
        g4SceneMetricMedians = localBuildG4SceneMetricMedianTable( ...
            g4PassiveBaselineMapAnalysis.MapSummaryTable);
        g4RawRateAuditSummary = ...
            g4PassiveBaselineMapAnalysis.FullRateAuditSummaryTable;
        localPlotG4RepresentativeMapGrid( ... %[output:2f5b3e00]
            g4PassiveBaselineMapAnalysis.RepresentativeMaps, "raw"); %[output:2f5b3e00]
        localPlotG4RepresentativeMapGrid( ... %[output:5dbe1ea9]
