function pipelineResults = localRunPlaceholderGate(pipelineResults, gateId)

if pipelineResults.StopPipeline
    return
end

gateIdx = localFindGateIndex(pipelineResults, gateId);

if gateIdx > 1
    previousGate = pipelineResults.GateResults(gateIdx - 1);

    if ~localGateAllowsDownstreamDevelopment(previousGate)
        pipelineResults.PipelineStatus = "blocked_by_upstream_gate";
        pipelineResults.NextGate = previousGate.GateId;
        pipelineResults.StopPipeline = true;
        pipelineResults.Message = localBuildUpstreamBlockMessage( ...
            previousGate);
        pipelineResults.GateResults(gateIdx).DevelopmentStatus = "blocked";
        pipelineResults.GateResults(gateIdx).Message = ...
            "Blocked by an upstream gate that has not established " + ...
            "downstream development readiness yet.";
        return
    end
end

if gateIdx > 1 && previousGate.DevelopmentStatus == ...
        "unblocked_with_dataset_caveat"
    pipelineResults.PipelineStatus = ...
        "stopped_after_last_implemented_gate_with_caveat";
    pipelineResults.Message = ...
        "This gate is still a placeholder. Stage 2 is analytically " + ...
        "valid but dataset-limited, so later development may continue " + ...
        "under caveat when this gate is implemented.";
    pipelineResults.GateResults(gateIdx).Message = ...
        "Placeholder only. Upstream development is unblocked under " + ...
        "caveat, but formal gate approval remains pending.";
else
    pipelineResults.PipelineStatus = "stopped_after_last_implemented_gate";
    pipelineResults.Message = ...
        "Pipeline stopped after the last implemented gate. This gate is " + ...
        "still a placeholder.";
    pipelineResults.GateResults(gateIdx).Message = ...
        "Placeholder only. Add the gate implementation here when it is ready.";
end

pipelineResults.NextGate = gateId;
pipelineResults.StopPipeline = true;
pipelineResults.GateResults(gateIdx).DevelopmentStatus = ...
    "placeholder_only";

end

function pipelineResults = localRecordG2Stage2Results(pipelineResults, ...
    stageResults)

gateId = "G2_RF_Health";
gateIdx = localFindGateIndex(pipelineResults, gateId);
pipelineResults.ExecutedGates = localAppendExecutedGate( ...
    pipelineResults.ExecutedGates, gateId);
pipelineResults.LastExecutedGate = gateId;
pipelineResults.GateResults(gateIdx).Implemented = true;
pipelineResults.GateResults(gateIdx).ExecutionStatus = ...
    "manual_review_executed";
pipelineResults.GateResults(gateIdx).Decision = "manual_review_nonfinal";
pipelineResults.GateResults(gateIdx).DevelopmentStatus = ...
    string(stageResults.DevelopmentReadiness);
pipelineResults.GateResults(gateIdx).BundleRoot = ...
    string(stageResults.BundleRoot);
pipelineResults.G2Stage2Result = stageResults;
pipelineResults.DevelopmentStatus = string(stageResults.DevelopmentReadiness);
pipelineResults.DevelopmentNote = ...
    string(stageResults.DevelopmentInterpretation);

if stageResults.DevelopmentReadiness == "ready_for_gate_progression"
    pipelineResults.NextGate = "G3_Sync";
    pipelineResults.StopPipeline = false;
    pipelineResults.PipelineStatus = ...
        "g2_stage2_ready_for_gate_progression";
    pipelineResults.Message = ...
        "Stage 2 is analytically valid and supports formal progression " + ...
        "review when the next stage is implemented.";
    pipelineResults.GateResults(gateIdx).Message = ...
        "Stage 2 manual review is analytically valid and ready for " + ...
        "formal progression review.";
elseif stageResults.DevelopmentReadiness == ...
        "unblocked_with_dataset_caveat"
    pipelineResults.NextGate = "G3_Sync";
    pipelineResults.StopPipeline = false;
    pipelineResults.PipelineStatus = "g2_stage2_development_caveated";
    pipelineResults.Message = ...
        "Stage 2 is analytically valid but dataset-limited. Later " + ...
        "development may continue under caveat when implemented.";
    pipelineResults.GateResults(gateIdx).Message = ...
        "Stage 2 manual review is analytically valid. Formal approval " + ...
        "remains pending, but downstream development may continue " + ...
        "under caveat.";
else
    pipelineResults.NextGate = gateId;
    pipelineResults.StopPipeline = true;
    pipelineResults.PipelineStatus = "g2_stage2_development_blocked";
    pipelineResults.Message = ...
        "Stage 2 did not establish a trustworthy analysis result. " + ...
        "Downstream development remains blocked.";
    pipelineResults.GateResults(gateIdx).Message = ...
        "Stage 2 manual review is blocked until the role mapping or " + ...
        "metric completeness issue is repaired.";
end

end

