function sceneMetricMedians = localBuildG4SceneMetricMedianTable( ...
    mapSummaryTable)

groupKeys = unique(mapSummaryTable(:, {'CpiLabel', 'WindowLabel'}), ...
    'rows');
rowCount = height(groupKeys);
cpiLabel = strings(rowCount, 1);
windowLabel = strings(rowCount, 1);
sceneObservabilityScore = zeros(rowCount, 1);
offOriginNonzeroDopplerEnergyFraction = zeros(rowCount, 1);
offOriginOccupiedFraction = zeros(rowCount, 1);
zeroDopplerRidgeEnergyFraction = zeros(rowCount, 1);
directPathToOffRidgeEnergy_dB = zeros(rowCount, 1);

for idx = 1:rowCount
    subset = mapSummaryTable(mapSummaryTable.CpiLabel == ...
        groupKeys.CpiLabel(idx) & mapSummaryTable.WindowLabel == ...
        groupKeys.WindowLabel(idx), :);
    cpiLabel(idx) = string(groupKeys.CpiLabel(idx));
    windowLabel(idx) = string(groupKeys.WindowLabel(idx));
    sceneObservabilityScore(idx) = median( ...
        subset.SceneObservabilityScore, "omitnan");
    offOriginNonzeroDopplerEnergyFraction(idx) = median( ...
        subset.OffOriginNonzeroDopplerEnergyFraction, "omitnan");
    offOriginOccupiedFraction(idx) = median( ...
        subset.OffOriginOccupiedFraction_abovePeakMinus20dB, "omitnan");
    zeroDopplerRidgeEnergyFraction(idx) = median( ...
        subset.ZeroDopplerRidgeEnergyFraction, "omitnan");
    directPathToOffRidgeEnergy_dB(idx) = median( ...
        subset.DirectPathToOffRidgeEnergy_dB, "omitnan");
end

sceneMetricMedians = table(cpiLabel, windowLabel, ...
    sceneObservabilityScore, offOriginNonzeroDopplerEnergyFraction, ...
    offOriginOccupiedFraction, zeroDopplerRidgeEnergyFraction, ...
    directPathToOffRidgeEnergy_dB, VariableNames = {'CpiLabel', ...
    'WindowLabel', 'SceneObservabilityScore', ...
    'OffOriginNonzeroDopplerEnergyFraction', ...
    'OffOriginOccupiedFraction_abovePeakMinus20dB', ...
    'ZeroDopplerRidgeEnergyFraction', ...
    'DirectPathToOffRidgeEnergy_dB'});
sceneMetricMedians = sortrows(sceneMetricMedians, ...
    {'CpiLabel', 'WindowLabel'});

end

function localPlotG4RepresentativeMapGrid(representativeMaps, axisMode)

axisMode = string(axisMode);
figure;
tiledlayout(3, 5, "TileSpacing", "compact", "Padding", "compact");

for idx = 1:numel(representativeMaps)
    nexttile;
    representativeMap = representativeMaps(idx);

    if axisMode == "display"
        delayAxis = representativeMap.DisplayDelayAxis_samples;
        dopplerAxis = representativeMap.DisplayDopplerAxis_Hz;
        plotTitle = sprintf("%s %s display", ...
            representativeMap.CpiLabel, representativeMap.WindowLabel);
    else
        delayAxis = representativeMap.DelayAxis_samples;
        dopplerAxis = representativeMap.DopplerAxis_Hz;
        plotTitle = sprintf("%s %s raw", ...
            representativeMap.CpiLabel, representativeMap.WindowLabel);
    end

    imagesc(delayAxis, dopplerAxis, representativeMap.Map_dB);
    axis xy;
    xlabel("Delay [samples]");
    ylabel("Doppler [Hz]");
    title(plotTitle);
    colorbar;
end

end

function localPlotG4DirectPathTrend(mapSummaryTable)

figure;
tiledlayout(2, 1, "TileSpacing", "compact", "Padding", "compact");
cpiLabels = unique(mapSummaryTable.CpiLabel);

nexttile;
hold on;
for idx = 1:numel(cpiLabels)
    subset = mapSummaryTable(mapSummaryTable.CpiLabel == cpiLabels(idx) & ...
        mapSummaryTable.WindowLabel == "center", :);
    plot(subset.Repetition, subset.RawDirectPathDelayOffset_samples, ...
        "-o", "DisplayName", cpiLabels(idx));
end
hold off;
xlabel("Repetition");
ylabel("Raw direct-path delay [samples]");
title("G4 Center-Window Direct-Path Delay Trend");
legend("Location", "best");

nexttile;
hold on;
for idx = 1:numel(cpiLabels)
    subset = mapSummaryTable(mapSummaryTable.CpiLabel == cpiLabels(idx) & ...
        mapSummaryTable.WindowLabel == "center", :);
    plot(subset.Repetition, subset.RawDirectPathDopplerOffset_Hz, ...
        "-o", "DisplayName", cpiLabels(idx));
end
hold off;
xlabel("Repetition");
ylabel("Raw direct-path Doppler [Hz]");
title("G4 Center-Window Direct-Path Doppler Trend");
legend("Location", "best");

end
