function interpretationText = localBuildG2Stage2PowerInterpretation(metrics)

medianPowerDelta = double( ...
    metrics.reference_minus_surveillance_power_db_median);

if medianPowerDelta < 0.0
    interpretationText = sprintf("Median reference minus surveillance power is %.3f dB. The accepted reference channel is weaker in whole-band in-band power, which points first to dataset, hardware, or acquisition limitations.", ...
        medianPowerDelta);
elseif medianPowerDelta < 3.0
    interpretationText = sprintf("Median reference minus surveillance power is %.3f dB. The accepted reference channel is stronger, but the margin is still modest.", ...
        medianPowerDelta);
else
    interpretationText = sprintf("Median reference minus surveillance power is %.3f dB. The accepted reference channel has a healthy whole-band power advantage.", ...
        medianPowerDelta);
end

end

function interpretationText = localBuildG2Stage2ClippingInterpretation( ...
    channelSummaryTable)

worstPeakHeadroom = min(channelSummaryTable.MinPeakHeadroom_dB);
worstNearRailFraction = max(channelSummaryTable.MaxNearRailFraction);

if worstNearRailFraction > 0.0
    interpretationText = sprintf("Worst near-rail fraction is %.6f and worst peak headroom is %.3f dB. Saturation pressure is present even though exact-rail clipping is not the main Stage 2 driver here.", ...
        worstNearRailFraction, worstPeakHeadroom);
else
    interpretationText = sprintf("Worst near-rail fraction is %.6f and worst peak headroom is %.3f dB. No severe clipping is reflected in the current Stage 2 verdict.", ...
        worstNearRailFraction, worstPeakHeadroom);
end

end

function interpretationText = localBuildG2Stage2DcInterpretation( ...
    channelSummaryTable)

worstDcSpike = max(channelSummaryTable.MaxDcSpike_dB);

if worstDcSpike >= 3.0
    interpretationText = sprintf("Worst DC spike is %.3f dB above the local PSD floor. DC or LO contamination is part of the current caveat set.", ...
        worstDcSpike);
else
    interpretationText = sprintf("Worst DC spike is %.3f dB above the local PSD floor. DC behavior is not the dominant Stage 2 concern in this session.", ...
        worstDcSpike);
end

end

function interpretationText = localBuildG2Stage2IqInterpretation( ...
    channelSummaryTable)

worstIqImpropriety = max(channelSummaryTable.MaxIqImpropriety);

if worstIqImpropriety >= 0.05
    interpretationText = sprintf("Worst IQ impropriety is %.4f. IQ and image behavior contributes to the current receiver caveat set.", ...
        worstIqImpropriety);
else
    interpretationText = sprintf("Worst IQ impropriety is %.4f. IQ and image proxies remain below the current diagnostic threshold.", ...
        worstIqImpropriety);
end

end

function interpretationText = localBuildG2Stage2ReceiverHealthInterpretation( ...
    channelSummaryTable)

worstNearRailFraction = max(channelSummaryTable.MaxNearRailFraction);
worstDcSpike = max(channelSummaryTable.MaxDcSpike_dB);
worstIqImpropriety = max(channelSummaryTable.MaxIqImpropriety);

if worstNearRailFraction > 0.0 || worstDcSpike >= 3.0 || ...
        worstIqImpropriety >= 0.05
    interpretationText = "At least one receiver-health proxy is part " + ...
        "of the current caveat set.";
else
    interpretationText = "Clipping, DC, and IQ proxies remain cleaner " + ...
        "than the role-based power-ordering result.";
end

end

