function joinedText = localJoinStringVector(values)

values = string(values(:));
values = strtrim(values);
values = values(strlength(values) > 0);

if isempty(values)
    joinedText = "";
    return
end

joinedText = strjoin(values, ", ");

end

function roleLabel = localInferChannelRoleLabel(channelLabel)

channelLabel = upper(strtrim(string(channelLabel)));

if contains(channelLabel, "RF0")
    roleLabel = "Surveillance";
elseif contains(channelLabel, "RF1")
    roleLabel = "Reference";
else
    roleLabel = "Unspecified";
end

end

function gateStatusTable = localBuildGateStatusTable(pipelineResults)

gateResults = pipelineResults.GateResults;
gateCount = numel(gateResults);
gateId = strings(gateCount, 1);
implemented = false(gateCount, 1);
executionStatus = strings(gateCount, 1);
decision = strings(gateCount, 1);
developmentStatus = strings(gateCount, 1);
bundleRoot = strings(gateCount, 1);
message = strings(gateCount, 1);

for idx = 1:gateCount
    gateId(idx) = gateResults(idx).GateId;
    implemented(idx) = gateResults(idx).Implemented;
    executionStatus(idx) = gateResults(idx).ExecutionStatus;
    decision(idx) = gateResults(idx).Decision;
    developmentStatus(idx) = gateResults(idx).DevelopmentStatus;
    bundleRoot(idx) = gateResults(idx).BundleRoot;
    message(idx) = gateResults(idx).Message;
end

gateStatusTable = table(gateId, implemented, executionStatus, decision, ...
    developmentStatus, bundleRoot, message, VariableNames = ...
    {'GateId', 'Implemented', 'ExecutionStatus', 'Decision', ...
    'DevelopmentStatus', 'BundleRoot', 'Message'});

end

function pipelineSummary = localBuildPipelineSummaryTable(pipelineResults)

pipelineSummary = table(pipelineResults.DatasetId, ...
    pipelineResults.RunTimestampZ, pipelineResults.PipelineStatus, ...
    pipelineResults.LastExecutedGate, pipelineResults.LastPassingGate, ...
    pipelineResults.NextGate, pipelineResults.DevelopmentStatus, ...
    numel(pipelineResults.ExecutedGates), ...
    VariableNames = {'DatasetId', 'RunTimestampZ', 'PipelineStatus', ...
    'LastExecutedGate', 'LastPassingGate', 'NextGate', ...
    'DevelopmentStatus', 'ExecutedGateCount'});

end

function value = localGateAllowsDownstreamDevelopment(gateResult)

executionAllowed = any(gateResult.ExecutionStatus == [ ...
    "executed"; ...
    "manual_review_executed" ...
    ]);
formalPass = gateResult.Decision == "pass";
developmentPass = any(gateResult.DevelopmentStatus == [ ...
    "ready_for_gate_progression"; ...
    "unblocked_with_dataset_caveat" ...
    ]);
value = executionAllowed && (formalPass || developmentPass);

end

function message = localBuildUpstreamBlockMessage(previousGate)

if previousGate.GateId == "G2_RF_Health" && ...
        previousGate.DevelopmentStatus == "blocked"
    message = "Later gate execution is blocked until G2 Stage 2 " + ...
        "establishes a trustworthy role mapping and receiver-integrity " + ...
        "interpretation.";
    return
end

if previousGate.GateId == "G2_RF_Health"
    message = "Later gate execution is blocked until the G2 manual-" + ...
        "review slices establish downstream development readiness.";
    return
end

message = "Later gate execution is blocked until the upstream gate has " + ...
    "executed and passed.";

end

function gateIdx = localFindGateIndex(pipelineResults, gateId)

gateIdx = find([pipelineResults.GateResults.GateId] == gateId, 1, "first");

if isempty(gateIdx)
    error("runPassiveBistaticPipeline:UnknownGate", ...
        "Unknown gate ID: %s", gateId);
end

end

function executedGates = localAppendExecutedGate(executedGates, gateId)

if any(executedGates == gateId)
    return
end

executedGates = [executedGates; gateId];

end


