%   data: {"dataType":"tabular","outputData":{"columnNames":["PanelName","EquationOrMethod","WhyItMatters","CurrentSessionReadout","DecisionUse"],"columns":5,"dataTypes":["string","string","string","string","string"],"header":"3×5 table","name":"g2Stage2Figure2Guide","rows":3,"type":"table","value":[["\"Receiver Mean Power By Accepted Role\"","\"P_mean,dBFS = 10*log10(mean(abs(x).^2) \/ FS^2)\"","\"Shows whether the accepted reference and surveillance channels are using sensible scale and whether one role is unexpectedly dominating whole-band energy.\"","\"Median mean power is reference -19.338 dBFS and surveillance -9.343 dBFS.\"","\"Supports the quantization-risk check and provides context for the role-power conclusion.\""],["\"Reference Power Advantage\"","\"DeltaP_ref-surv = P_ref,dBFS - P_surv,dBFS\"","\"Answers the core Stage 2 role-ordering question: does the accepted reference actually look stronger than surveillance?\"","\"Reference minus surveillance power ranges from -10.171 dB to -9.659 dB with median -9.969 dB. The Stage 2 minimum threshold is 0.0 dB and the target margin is 3.0 dB.\"","\"Values below 0 dB mean the accepted reference is weaker than surveillance, which drives the current retune recommendation.\""],["\"Peak Headroom By Accepted Role\"","\"H_pk = 20*log10(FS \/ max(abs(real(x)), abs(imag(x))))\"","\"Shows how much amplitude margin remains before hard clipping or near-rail pressure becomes a concern.\"","\"Minimum peak headroom is reference 10.643 dB and surveillance 0.197 dB.\"","\"Very low headroom by itself does not fail Stage 2, but it helps explain whether clipping pressure is plausible.\""]]}}
