%   data: {"dataType":"tabular","outputData":{"columnNames":["PanelName","EquationOrMethod","WhyItMatters","CurrentSessionReadout","DecisionUse"],"columns":5,"dataTypes":["string","string","string","string","string"],"header":"4×5 table","name":"g2Stage2Figure3Guide","rows":4,"type":"table","value":[["\"Near-Rail Occupancy\"","\"mean(abs(real(x)) >= 0.98*FS or abs(imag(x)) >= 0.98*FS) with exact-rail samples tracked separately\"","\"Shows whether the digitizer is spending measurable time near full scale, which is a precursor to clipping distortion.\"","\"Worst near-rail fraction is 0.000000. The severe threshold is 1.0e-04 and exact-rail samples would also hard-fail clipping.\"","\"Severe near-rail occupancy or any exact-rail samples can push Stage 2 to reject.\""],["\"DC Spike Relative To Local PSD Floor\"","\"D_DC = 10*log10(PSD(0) \/ median(local non-DC PSD bins))\"","\"Shows whether DC or LO leakage is large enough to contaminate near-zero interpretation.\"","\"Worst DC spike is 0.341 dB. The diagnostic threshold is 3.0 dB and the severe threshold is 10.0 dB.\"","\"Moderate DC leakage can force retune and severe DC leakage can contribute to hard fail.\""],["\"I\/Q Amplitude Imbalance Proxy\"","\"A_IQ = 20*log10(std(I_centered) \/ std(Q_centered))\"","\"Shows whether one quadrature arm is carrying systematically different scale than the other.\"","\"Worst absolute amplitude-imbalance proxy is 0.294 dB. The diagnostic threshold is 1.0 dB and the severe threshold is 3.0 dB.\"","\"Amplitude imbalance is part of the IQ diagnostic and severe IQ screen.\""],["\"I\/Q Image-Risk Proxy\"","\"kappa = abs(mean(x.^2)) \/ mean(abs(x).^2)\"","\"Shows whether the complex signal departs from proper circular behavior in a way that can imply image leakage or quadrature problems.\"","\"Worst impropriety is 0.0341. The diagnostic threshold is 0.050 and the severe threshold is 0.150.\"","\"Impropriety is the most direct Stage 2 image-risk proxy and is used in both diagnostic and severe IQ thresholds.\""]]}}
